import json
from datetime import datetime
import numpy as np
from decimal import Decimal

class CustomJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        # Handle datetime objects
        if isinstance(obj, datetime):
            return obj.isoformat()
        # Handle numpy arrays
        elif isinstance(obj, np.ndarray):
            return obj.tolist()
        # Handle Decimal objects
        elif isinstance(obj, Decimal):
            return float(obj)
        # Let the base class handle it (will raise TypeError for unsupported types)
        return super().default(obj)

def task_func(my_obj):
    """
    Serialize an object to a JSON string, handling complex data types.

    Args:
        my_obj: The object to serialize

    Returns:
        str: The serialized JSON string

    Raises:
        TypeError: If an unsupported type is encountered
    """
    return json.dumps(my_obj, cls=CustomJSONEncoder)

