import pandas as pd

def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    def reverse_matching_words(text, pattern):
        words = text.split()
        matching_words = [word for word in words if re.search(pattern, word)]

        # Reverse the matching words
        matching_words_reversed = matching_words[::-1]

        # Reconstruct the text
        result_words = []
        matching_index = 0
        for word in words:
            if re.search(pattern, word):
                result_words.append(matching_words_reversed[matching_index])
                matching_index += 1
            else:
                result_words.append(word)

        return ' '.join(result_words)

    if not pattern:
        return df.copy()

    result_df = df.copy()
    result_df[column_name] = result_df[column_name].apply(lambda x: reverse_matching_words(str(x), pattern))

    return result_df

