import numpy as np
import pandas as pd

def task_func(products, n_samples=100, sales_lower=50, sales_upper=200, profit_margin_min=0.1, profit_margin_max=0.5, random_seed=42):
    # Type checking for products
    if not isinstance(products, list):
        raise TypeError("products must be a list of strings")

    if not all(isinstance(p, str) for p in products):
        raise TypeError("products must be a list of strings")

    # Type checking for numeric parameters
    numeric_params = [
        ('sales_lower', sales_lower),
        ('sales_upper', sales_upper),
        ('profit_margin_min', profit_margin_min),
        ('profit_margin_max', profit_margin_max)
    ]

    for param_name, param_value in numeric_params:
        if not isinstance(param_value, (int, float, np.integer, np.floating)):
            raise TypeError(f"{param_name} must be numeric")

    # Validate n_samples
    if isinstance(n_samples, bool) or not isinstance(n_samples, (int, np.integer)) or n_samples <= 0:
        raise ValueError("n_samples must be a positive integer")

    # Validate sales range
    if sales_lower > sales_upper:
        raise ValueError("sales_lower cannot be greater than sales_upper")

    # Set random seed
    np.random.seed(random_seed)

    # Generate data
    data = []
    for product in products:
        for _ in range(n_samples):
            sales = np.random.uniform(sales_lower, sales_upper)
            profit_margin = np.random.uniform(profit_margin_min, profit_margin_max)
            profit = sales * profit_margin
            data.append({
                'product': product,
                'sales': sales,
                'profit': profit
            })

    # Create DataFrame and aggregate
    if data:
        df = pd.DataFrame(data)

        # Aggregate by product
        aggregated = df.groupby('product').agg({
            'sales': 'sum',
            'profit': 'sum'
        }).reset_index()

        # Sort by profit descending
        aggregated = aggregated.sort_values('profit', ascending=False).reset_index(drop=True)
    else:
        # Return empty DataFrame with correct columns when no data is generated
        aggregated = pd.DataFrame(columns=['product', 'sales', 'profit'])

    return aggregated

