import pandas as pd

def task_func(obj_list, attr):
    # Extract attribute values from all objects that have the attribute
    attr_values = []
    for obj in obj_list:
        if hasattr(obj, attr):
            attr_values.append(getattr(obj, attr))

    # Count the frequencies using Counter
    counter = collections.Counter(attr_values)

    # Convert to DataFrame
    if counter:
        df = pd.DataFrame(list(counter.items()), columns=['attribute', 'count'])
    else:
        df = pd.DataFrame(columns=['attribute', 'count'])

    return df

